CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "ItemCategories" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Description" text,
    CONSTRAINT "PK_ItemCategories" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Username" character varying(100) NOT NULL,
    "PasswordHash" text NOT NULL,
    "Email" character varying(100),
    "Phone" character varying(30),
    "ShippingAddress" character varying(200),
    "Role" integer NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "Items" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Description" text,
    "Price" numeric(18,2) NOT NULL,
    "Discount" double precision NOT NULL,
    "ImageUrl" text,
    "CategoryId" bigint,
    "IsDeleted" boolean NOT NULL,
    "Discriminator" character varying(8) NOT NULL,
    "Age" smallint,
    "ColorType" integer,
    "GenderType" integer,
    "SpeciesType" integer,
    "TraitsId" bigint,
    CONSTRAINT "PK_Items" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Items_ItemCategories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "ItemCategories" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Carts" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint,
    CONSTRAINT "PK_Carts" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Carts_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Orders" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "UserId" bigint,
    "Status" text,
    "Timestamp" timestamp with time zone NOT NULL,
    "ShippingAddress" text NOT NULL,
    "Total" numeric NOT NULL,
    CONSTRAINT "PK_Orders" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Orders_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE SET NULL
);

CREATE TABLE "RefreshTokens" (
    "Token" text NOT NULL,
    "UserID" bigint NOT NULL,
    "IssuedAt" timestamp with time zone NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_RefreshTokens" PRIMARY KEY ("Token"),
    CONSTRAINT "FK_RefreshTokens_Users_UserID" FOREIGN KEY ("UserID") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Traits" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "ParrotId" bigint NOT NULL,
    "Size" integer,
    "NoiseLevel" integer,
    "Sociability" integer,
    "Trainability" integer,
    "Talkativeness" integer,
    "ChewingRisk" integer,
    "CareComplexity" integer,
    "KidSafety" integer,
    CONSTRAINT "PK_Traits" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Traits_Items_ParrotId" FOREIGN KEY ("ParrotId") REFERENCES "Items" ("Id") ON DELETE CASCADE
);

CREATE TABLE "CartItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CartId" bigint NOT NULL,
    "ItemId" bigint NOT NULL,
    "Qty" integer NOT NULL,
    CONSTRAINT "PK_CartItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_CartItems_Carts_CartId" FOREIGN KEY ("CartId") REFERENCES "Carts" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_CartItems_Items_ItemId" FOREIGN KEY ("ItemId") REFERENCES "Items" ("Id") ON DELETE CASCADE
);

CREATE TABLE "OrderItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "LinkedItemId" bigint,
    "Name" character varying(100) NOT NULL,
    "Description" text,
    "PriceAtOrderTime" numeric(18,2) NOT NULL,
    "Qty" integer NOT NULL,
    "ImageUrl" text,
    "OrderId" bigint,
    "Discriminator" character varying(13) NOT NULL,
    "Age" smallint,
    "ColorType" integer,
    "GenderType" integer,
    "SpeciesType" integer,
    CONSTRAINT "PK_OrderItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OrderItems_Items_LinkedItemId" FOREIGN KEY ("LinkedItemId") REFERENCES "Items" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_OrderItems_Orders_OrderId" FOREIGN KEY ("OrderId") REFERENCES "Orders" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_CartItems_CartId" ON "CartItems" ("CartId");

CREATE INDEX "IX_CartItems_ItemId" ON "CartItems" ("ItemId");

CREATE UNIQUE INDEX "IX_Carts_UserId" ON "Carts" ("UserId");

CREATE INDEX "IX_Items_CategoryId" ON "Items" ("CategoryId");

CREATE INDEX "IX_OrderItems_LinkedItemId" ON "OrderItems" ("LinkedItemId");

CREATE INDEX "IX_OrderItems_OrderId" ON "OrderItems" ("OrderId");

CREATE INDEX "IX_Orders_UserId" ON "Orders" ("UserId");

CREATE INDEX "IX_RefreshTokens_UserID" ON "RefreshTokens" ("UserID");

CREATE UNIQUE INDEX "IX_Traits_ParrotId" ON "Traits" ("ParrotId");

CREATE UNIQUE INDEX "IX_Users_Email" ON "Users" ("Email");

CREATE UNIQUE INDEX "IX_Users_Username" ON "Users" ("Username");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261021211732_init', '10.0.2');

COMMIT;

